fn all_digits(s: Str) -> Bool {
  if s.is_empty() {
    return false
  }
  for c in s.codes() {
    if c < 48 or c > 57 {
      return false
    }
  }
  return true
}

// The amount as a whole number; 0 when it is not made of digits.
fn amount_of(s: Str) -> Int {
  if all_digits(s) == false {
    return 0
  }
  return s.to_int().unwrap_or(0)
}

pub fn ledger(ops: List[Str]) -> Result[Map[Str, Int], Str] {
  var acc: Map[Str, Int] = Map {}
  for op in ops {
    let parts = op.split(" ")
    let verb = parts.get_or(0, "")
    if verb == "open" {
      if parts.len() != 2 {
        return Err("bad op")
      }
      let name = parts.get_or(1, "")
      if acc.has(name) {
        return Err("exists " + name)
      }
      acc = acc.set(name, 0)
    } else if verb == "dep" or verb == "wd" {
      if parts.len() != 3 {
        return Err("bad op")
      }
      let name = parts.get_or(1, "")
      let amount = amount_of(parts.get_or(2, ""))
      if amount <= 0 {
        return Err("bad op")
      }
      if acc.has(name) == false {
        return Err("unknown " + name)
      }
      let bal = acc.get(name).unwrap_or(0)
      if verb == "dep" {
        acc = acc.set(name, bal + amount)
      } else {
        if bal < amount {
          return Err("insufficient " + name)
        }
        acc = acc.set(name, bal - amount)
      }
    } else if verb == "move" {
      if parts.len() != 4 {
        return Err("bad op")
      }
      let src = parts.get_or(1, "")
      let dst = parts.get_or(2, "")
      let amount = amount_of(parts.get_or(3, ""))
      if amount <= 0 {
        return Err("bad op")
      }
      if acc.has(src) == false {
        return Err("unknown " + src)
      }
      if acc.has(dst) == false {
        return Err("unknown " + dst)
      }
      let bal = acc.get(src).unwrap_or(0)
      if bal < amount {
        return Err("insufficient " + src)
      }
      acc = acc.set(src, bal - amount)
      acc = acc.set(dst, acc.get(dst).unwrap_or(0) + amount)
    } else {
      return Err("bad op")
    }
  }
  return Ok(acc)
}
